CREATE TABLE "RosterRole" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "nameKey" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "RosterRole_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "RosterRole_nameKey_key" ON "RosterRole"("nameKey");
INSERT INTO "RosterRole" ("id", "name", "nameKey", "updatedAt") VALUES ('role-caja','Caja','caja',CURRENT_TIMESTAMP), ('role-barra','Barra','barra',CURRENT_TIMESTAMP), ('role-mozos','Mozos','mozos',CURRENT_TIMESTAMP), ('role-seguridad','Seguridad','seguridad',CURRENT_TIMESTAMP), ('role-animacion','Animación','animacion',CURRENT_TIMESTAMP), ('role-djs','DJs','djs',CURRENT_TIMESTAMP), ('role-multimedia','Multimedia','multimedia',CURRENT_TIMESTAMP), ('role-otros','Otros','otros',CURRENT_TIMESTAMP);
CREATE TABLE "RosterAssignment" ("id" TEXT NOT NULL, "businessDay" TEXT NOT NULL, "personId" TEXT NOT NULL, "roleId" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdBy" TEXT NOT NULL, "updatedBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "RosterAssignment_pkey" PRIMARY KEY ("id"), CONSTRAINT "RosterAssignment_personId_fkey" FOREIGN KEY ("personId") REFERENCES "Person"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "RosterAssignment_roleId_fkey" FOREIGN KEY ("roleId") REFERENCES "RosterRole"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "RosterAssignment_businessDay_personId_roleId_key" ON "RosterAssignment"("businessDay", "personId", "roleId");
CREATE INDEX "RosterAssignment_businessDay_active_roleId_idx" ON "RosterAssignment"("businessDay", "active", "roleId");
CREATE TABLE "RosterEvent" ("id" TEXT NOT NULL, "businessDay" TEXT NOT NULL, "assignmentId" TEXT NOT NULL, "personName" TEXT NOT NULL, "roleName" TEXT NOT NULL, "action" TEXT NOT NULL, "actorId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "RosterEvent_pkey" PRIMARY KEY ("id"), CONSTRAINT "RosterEvent_assignmentId_fkey" FOREIGN KEY ("assignmentId") REFERENCES "RosterAssignment"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "RosterEvent_businessDay_createdAt_idx" ON "RosterEvent"("businessDay", "createdAt");
